package com.ryanjei.orushio.pve.map;
import static org.junit.jupiter.api.Assertions.*;import com.ryanjei.orushio.pve.application.*;import com.ryanjei.orushio.pve.domain.*;import com.ryanjei.orushio.pve.persistence.ActiveSessionRepository;import java.nio.file.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
class DefaultMapAdministrationServiceTest{
 @TempDir Path temp;
 @Test void setupStartPointAreaSaveAndDiscard()throws Exception{Fixture f=fixture();UUID admin=UUID.randomUUID();assertTrue(f.service.startSetup("map-a",admin,"IDLE").active());f.service.selectField(admin,"farmSpawn",false);f.service.recordClick(admin,new BlockPoint(1,2,3,0,0),true);f.service.selectField(admin,"enemyZones",true);f.service.recordClick(admin,new BlockPoint(0,0,0,0,0),false);f.service.recordClick(admin,new BlockPoint(2,3,4,0,0),true);MapProfile saved=f.service.saveSetup(f.games.current().sessionId().toString());assertEquals(1,saved.points().get("farmSpawn").size());assertEquals(1,saved.areas().get("enemyZones").size());assertEquals(GameState.IDLE,f.games.current().state());assertFalse(Files.exists(f.gateway.last.directory()));f.service.startSetup("map-a",admin,"IDLE");f.service.selectField(admin,"shopPoints",false);f.service.recordClick(admin,new BlockPoint(9,9,9,0,0),true);f.service.discardSetup(f.games.current().sessionId().toString());assertNull(f.repository.find(new MapProfileId("map-a")).orElseThrow().points().get("shopPoints"));}
 @Test void wrongSessionSaveDoesNotMutateAnything()throws Exception{Fixture f=fixture();UUID admin=UUID.randomUUID();MapProfile before=f.repository.find(new MapProfileId("map-a")).orElseThrow();f.service.startSetup("map-a",admin,"IDLE");f.service.selectField(admin,"farmSpawn",false);f.service.recordClick(admin,new BlockPoint(1,2,3,0,0),true);Path world=f.gateway.last.directory();assertThrows(DomainException.class,()->f.service.saveSetup(UUID.randomUUID().toString()));assertTrue(Files.exists(world));assertTrue(f.service.setup().active());assertEquals(GameState.MAP_SETUP,f.games.current().state());assertEquals(before,f.repository.find(new MapProfileId("map-a")).orElseThrow());assertEquals(0,f.gateway.unloads);}
 @Test void wrongSessionDiscardDoesNotMutateAnything()throws Exception{Fixture f=fixture();UUID admin=UUID.randomUUID();MapProfile before=f.repository.find(new MapProfileId("map-a")).orElseThrow();f.service.startSetup("map-a",admin,"IDLE");Path world=f.gateway.last.directory();assertThrows(DomainException.class,()->f.service.discardSetup(UUID.randomUUID().toString()));assertTrue(Files.exists(world));assertTrue(f.service.setup().active());assertEquals(GameState.MAP_SETUP,f.games.current().state());assertEquals(before,f.repository.find(new MapProfileId("map-a")).orElseThrow());assertEquals(0,f.gateway.unloads);}
 @Test void singlePointAndAreaAreReplaced()throws Exception{Fixture f=fixture();UUID admin=UUID.randomUUID();f.service.startSetup("map-a",admin,"IDLE");BlockPoint a=new BlockPoint(1,1,1,0,0),b=new BlockPoint(2,2,2,0,0);f.service.selectField(admin,"farmSpawn",false);f.service.recordClick(admin,a,true);f.service.recordClick(admin,b,true);f.service.selectField(admin,"farmRegion",true);f.service.recordClick(admin,a,false);f.service.recordClick(admin,b,true);BlockPoint c=new BlockPoint(5,5,5,0,0),d=new BlockPoint(7,7,7,0,0);f.service.recordClick(admin,c,false);f.service.recordClick(admin,d,true);MapProfile saved=f.service.saveSetup(f.games.current().sessionId().toString());assertEquals(List.of(b),saved.points().get("farmSpawn"));assertEquals(List.of(Cuboid.between(c,d)),saved.areas().get("farmRegion"));}
 @Test void partialLoadFailureInvokesUnloadBeforeOwnedDirectoryDelete()throws Exception{Fixture f=fixture();f.gateway.failAfterLoad=true;assertThrows(MapIoException.class,()->f.service.startSetup("map-a",UUID.randomUUID(),"IDLE"));assertEquals(1,f.gateway.unloads);assertFalse(Files.exists(f.gateway.last.directory()));assertEquals(GameState.IDLE,f.games.current().state());}
 @Test void partialLoadRollbackFailureIsQuarantined()throws Exception{Fixture f=fixture();f.gateway.failAfterLoad=true;f.gateway.failUnload=true;assertThrows(MapIoException.class,()->f.service.startSetup("map-a",UUID.randomUUID(),"IDLE"));assertTrue(Files.exists(f.gateway.last.directory()));assertEquals(GameState.MAP_SETUP,f.games.current().state());assertTrue(f.service.setup().active());assertTrue(f.manager.recoveryRequired());assertTrue(f.manager.startupRecoveryWarning().orElseThrow().contains(f.gateway.last.worldName()));assertEquals(f.gateway.last,f.manager.recoveryTarget().orElseThrow());assertThrows(MapIoException.class,()->f.manager.create(MapProfileTest.empty("other"),"setup"));}
 @Test void partialLoadCleanupSessionSaveFailureKeepsWorldAndDraft()throws Exception{Fixture f=fixture(new FailingCloseSession());f.gateway.failAfterLoad=true;assertThrows(MapIoException.class,()->f.service.startSetup("map-a",UUID.randomUUID(),"IDLE"));assertTrue(Files.exists(f.gateway.last.directory()));assertTrue(f.service.setup().active());assertEquals(GameState.MAP_SETUP,f.games.current().state());assertEquals(1,f.gateway.unloads);}
 @Test void saveCleanupFailureEntersRecoveryStateAfterSessionClosed()throws Exception{Fixture f=fixture();UUID admin=UUID.randomUUID();f.service.startSetup("map-a",admin,"IDLE");f.service.selectField(admin,"farmSpawn",false);f.service.recordClick(admin,new BlockPoint(8,8,8,0,0),true);f.gateway.failUnload=true;String session=f.games.current().sessionId().toString();assertThrows(MapIoException.class,()->f.service.saveSetup(session));assertEquals(new BlockPoint(8,8,8,0,0),f.repository.find(new MapProfileId("map-a")).orElseThrow().points().get("farmSpawn").getFirst());assertTrue(f.service.setup().active());assertEquals(GameState.IDLE,f.games.current().state());assertTrue(Files.exists(f.gateway.last.directory()));assertTrue(f.manager.recoveryRequired());}
 @Test void saveClosePersistenceFailureLeavesRetryableSetup()throws Exception{FailingCloseSession sessions=new FailingCloseSession();Fixture f=fixture(sessions);UUID admin=UUID.randomUUID();MapProfile before=f.repository.find(new MapProfileId("map-a")).orElseThrow();f.service.startSetup("map-a",admin,"IDLE");f.service.selectField(admin,"farmSpawn",false);f.service.recordClick(admin,new BlockPoint(4,4,4,0,0),true);assertThrows(RuntimeException.class,()->f.service.saveSetup(f.games.current().sessionId().toString()));assertEquals(before,f.repository.find(new MapProfileId("map-a")).orElseThrow());assertTrue(Files.exists(f.gateway.last.directory()));assertTrue(f.service.setup().active());assertEquals(GameState.MAP_SETUP,f.games.current().state());assertFalse(f.manager.recoveryRequired());assertEquals(0,f.gateway.unloads);}
 @Test void discardClosePersistenceFailureLeavesRetryableSetup()throws Exception{FailingCloseSession sessions=new FailingCloseSession();Fixture f=fixture(sessions);UUID admin=UUID.randomUUID();MapProfile before=f.repository.find(new MapProfileId("map-a")).orElseThrow();f.service.startSetup("map-a",admin,"IDLE");assertThrows(RuntimeException.class,()->f.service.discardSetup(f.games.current().sessionId().toString()));assertEquals(before,f.repository.find(new MapProfileId("map-a")).orElseThrow());assertTrue(Files.exists(f.gateway.last.directory()));assertTrue(f.service.setup().active());assertEquals(GameState.MAP_SETUP,f.games.current().state());assertFalse(f.manager.recoveryRequired());assertEquals(0,f.gateway.unloads);}
 @Test void ownedMapDeleteRemovesFilesAndProfile()throws Exception{Fixture f=fixture();f.service.delete("map-a");assertFalse(Files.exists(temp.resolve("maps/map-a")));assertTrue(f.repository.find(new MapProfileId("map-a")).isEmpty());}
 @Test void deleteRefusesMissingOwnershipMarker()throws Exception{Fixture f=fixture();Files.delete(temp.resolve("maps/map-a/.orushio-map-owner"));assertThrows(IllegalStateException.class,()->f.service.delete("map-a"));assertTrue(Files.exists(temp.resolve("maps/map-a/template/level.dat")));assertTrue(f.repository.find(new MapProfileId("map-a")).isPresent());}
 @Test void unauthorizedPlayerIsRejected()throws Exception{Fixture f=fixture();UUID admin=UUID.randomUUID();f.service.startSetup("map-a",admin,"IDLE");assertThrows(SecurityException.class,()->f.service.selectField(UUID.randomUUID(),"farmSpawn",false));}
 private Fixture fixture()throws Exception{return fixture(new MemorySession());}private Fixture fixture(ActiveSessionRepository sessions)throws Exception{Path maps=temp.resolve("maps"),worlds=temp.resolve("worlds"),template=maps.resolve("map-a/template");Files.createDirectories(template);Files.writeString(template.resolve("level.dat"),"x");Files.writeString(maps.resolve("map-a/.orushio-map-owner"),"map-a");MemoryProfiles profiles=new MemoryProfiles();profiles.save(MapProfileTest.empty("map-a"));DefaultGameApplicationService games=new DefaultGameApplicationService(sessions);FakeWorld gateway=new FakeWorld();TemporaryWorldManager manager=new TemporaryWorldManager(maps,worlds);var service=new DefaultMapAdministrationService(maps,profiles,new SafeWorldZipImporter(maps,SafeWorldZipImporter.Limits.defaults()),manager,gateway,games,new MapSelectionService(new Random(1)));return new Fixture(service,profiles,games,gateway,manager);}
 private record Fixture(DefaultMapAdministrationService service,MemoryProfiles repository,DefaultGameApplicationService games,FakeWorld gateway,TemporaryWorldManager manager){}private static final class MemoryProfiles implements MapProfileRepository{final Map<MapProfileId,MapProfile> values=new HashMap<>();public List<MapProfile> findAll(){return List.copyOf(values.values());}public Optional<MapProfile> find(MapProfileId id){return Optional.ofNullable(values.get(id));}public void save(MapProfile p){values.put(p.mapId(),p);}public void delete(MapProfileId id){values.remove(id);}}private static class MemorySession implements ActiveSessionRepository{GameSession value;public Optional<GameSession> load(){return Optional.ofNullable(value);}public void save(GameSession s){value=s;}}private static final class FailingCloseSession extends MemorySession{int saves;@Override public void save(GameSession s){if(++saves==2)throw new RuntimeException("IDLE save failed");super.save(s);}}private static final class FakeWorld implements MapWorldGateway{TemporaryWorldManager.OwnedWorld last;int unloads;boolean failAfterLoad,failUnload;public void loadForSetup(TemporaryWorldManager.OwnedWorld w,UUID a){last=w;if(failAfterLoad)throw new MapIoException("TEST","load後失敗");}public void unload(TemporaryWorldManager.OwnedWorld w){assertEquals(last,w);unloads++;if(failUnload)throw new MapIoException("TEST","unload失敗");}}
}
